import subprocess, pathlib, os
base="/tmp/checktest"
def hv(fn):
    r=subprocess.run(["/workspace/executable","--no-names",fn],capture_output=True,cwd=base)
    return r.stdout.decode().strip()
def rchk(inp):
    r=subprocess.run(["/workspace/executable","-c"],input=inp.encode(),capture_output=True,cwd=base)
    print(repr(inp),r.returncode,r.stdout,r.stderr)
for name,data in [("a",b"A"),("a\\",b"ASLASH"),("a\n",b"ANL"),("a\r",b"ACR"),("a\\n",b"ABACKN")]:
    open(os.path.join(base,name),"wb").write(data)
    print(repr(name), hv(name))
# file a exists, a\ exists
hA=hv("a"); hAS=hv("a\\")
for hv_, fntext in [(hA,r"a"),(hAS,r"a\\"),(hA,r"a\\"),(hAS,r"a\""),(hA,r"a\")]:
    # fntext in python raw: r"a\\" = a\\ (2 chars \ \? let's just explicitly below)
    pass
cases=[
 (hA, "a\\"), # a + single trailing backslash in line text
 (hAS, "a\\"),
 (hA, "a\\\\"), # a + double backslash text
 (hAS, "a\\\\"),
]
for hv_, fntext in cases:
    rchk(f"\\{hv_}  {fntext}\n")
# sequences: \\r etc
for fn, txt in [("a\n","a\\n"),("a\r","a\\r"),("a\\n","a\\\\n"),("a\n","a\\\\n")]:
    rchk(f"\\{hv(fn)}  {txt}\n")
# invalid escape chars
for txt in [r"a\é",r"a\ b",r"\a"]:
    rchk(f"\\{hA}  {txt}\n")
PY
"}

