// A portable BLAKE3 implementation written from the algorithm
// description: a 1024-byte chunk Merkle tree using the compression
// function below, with regular, keyed, and key-derivation modes and
// extendable output.

pub const OUT_LEN: usize = 32;
pub const KEY_LEN: usize = 32;
const BLOCK_LEN: usize = 64;
const CHUNK_LEN: u64 = 1024;

const IV: [u32; 8] = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
];

const FLAG_CHUNK_START: u32 = 1 << 0;
const FLAG_CHUNK_END: u32 = 1 << 1;
const FLAG_PARENT: u32 = 1 << 2;
const FLAG_ROOT: u32 = 1 << 3;
const FLAG_KEYED_HASH: u32 = 1 << 4;
const FLAG_DERIVE_KEY_CONTEXT: u32 = 1 << 5;
const FLAG_DERIVE_KEY_MATERIAL: u32 = 1 << 6;

const MSG_PERMUTATION: [usize; 16] = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8];

fn g(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, mx: u32, my: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(mx);
    state[d] = (state[d] ^ state[a]).rotate_right(16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(my);
    state[d] = (state[d] ^ state[a]).rotate_right(8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(7);
}

fn round_fn(state: &mut [u32; 16], m: &[u32; 16]) {
    g(state, 0, 4, 8, 12, m[0], m[1]);
    g(state, 1, 5, 9, 13, m[2], m[3]);
    g(state, 2, 6, 10, 14, m[4], m[5]);
    g(state, 3, 7, 11, 15, m[6], m[7]);
    g(state, 0, 5, 10, 15, m[8], m[9]);
    g(state, 1, 6, 11, 12, m[10], m[11]);
    g(state, 2, 7, 8, 13, m[12], m[13]);
    g(state, 3, 4, 9, 14, m[14], m[15]);
}

fn permute(m: &mut [u32; 16]) {
    let old = *m;
    for i in 0..16 {
        m[i] = old[MSG_PERMUTATION[i]];
    }
}

fn compress(
    cv: &[u32; 8],
    block_words: &[u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
) -> [u32; 16] {
    let mut state = [
        cv[0], cv[1], cv[2], cv[3], cv[4], cv[5], cv[6], cv[7],
        IV[0], IV[1], IV[2], IV[3],
        counter as u32, (counter >> 32) as u32, block_len, flags,
    ];
    let mut msg = *block_words;
    round_fn(&mut state, &msg);
    for _ in 0..6 {
        permute(&mut msg);
        round_fn(&mut state, &msg);
    }
    let mut out = [0u32; 16];
    for i in 0..8 {
        out[i] = state[i] ^ state[i + 8];
        out[i + 8] = state[i + 8] ^ cv[i];
    }
    out
}

fn words_from_block(block: &[u8; BLOCK_LEN]) -> [u32; 16] {
    let mut words = [0u32; 16];
    for i in 0..16 {
        words[i] = u32::from_le_bytes([
            block[i * 4],
            block[i * 4 + 1],
            block[i * 4 + 2],
            block[i * 4 + 3],
        ]);
    }
    words
}

fn words_from_key(key: &[u8; KEY_LEN]) -> [u32; 8] {
    let mut words = [0u32; 8];
    for i in 0..8 {
        words[i] = u32::from_le_bytes([
            key[i * 4],
            key[i * 4 + 1],
            key[i * 4 + 2],
            key[i * 4 + 3],
        ]);
    }
    words
}

/// The not-yet-root output of a chunk or a parent node. It can either
/// be reduced to a chaining value or expanded into root output bytes.
#[derive(Clone)]
pub struct Output {
    input_cv: [u32; 8],
    block_words: [u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
}

impl Output {
    pub fn chaining_value(&self) -> [u32; 8] {
        let out = compress(
            &self.input_cv,
            &self.block_words,
            self.counter,
            self.block_len,
            self.flags,
        );
        let mut cv = [0u32; 8];
        cv.copy_from_slice(&out[..8]);
        cv
    }

    fn root_block(&self, block_counter: u64) -> [u8; 64] {
        let out = compress(
            &self.input_cv,
            &self.block_words,
            block_counter,
            self.block_len,
            self.flags | FLAG_ROOT,
        );
        let mut bytes = [0u8; 64];
        for i in 0..16 {
            bytes[i * 4..i * 4 + 4].copy_from_slice(&out[i].to_le_bytes());
        }
        bytes
    }
}

/// A stateful XOF reader positioned at an arbitrary byte offset.
pub struct XofReader {
    output: Output,
    block_counter: u64,
    block: [u8; 64],
    offset: usize,
}

impl XofReader {
    pub fn new(output: Output, seek: u64) -> Self {
        let mut reader = Self {
            block_counter: seek / 64,
            block: [0u8; 64],
            offset: (seek % 64) as usize,
            output,
        };
        reader.block = reader.output.root_block(reader.block_counter);
        reader
    }

    pub fn fill(&mut self, mut dest: &mut [u8]) {
        while !dest.is_empty() {
            if self.offset == 64 {
                self.block_counter = self.block_counter.wrapping_add(1);
                self.block = self.output.root_block(self.block_counter);
                self.offset = 0;
            }
            let take = std::cmp::min(64 - self.offset, dest.len());
            dest[..take].copy_from_slice(&self.block[self.offset..self.offset + take]);
            self.offset += take;
            dest = &mut dest[take..];
        }
    }
}

#[derive(Clone)]
struct ChunkState {
    cv: [u32; 8],
    chunk_counter: u64,
    buf: [u8; BLOCK_LEN],
    buf_len: usize,
    blocks_compressed: u8,
    flags: u32,
}

impl ChunkState {
    fn new(key: [u32; 8], chunk_counter: u64, flags: u32) -> Self {
        Self {
            cv: key,
            chunk_counter,
            buf: [0u8; BLOCK_LEN],
            buf_len: 0,
            blocks_compressed: 0,
            flags,
        }
    }

    fn len(&self) -> usize {
        self.blocks_compressed as usize * BLOCK_LEN + self.buf_len
    }

    fn start_flag(&self) -> u32 {
        if self.blocks_compressed == 0 {
            FLAG_CHUNK_START
        } else {
            0
        }
    }

    fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.buf_len == BLOCK_LEN {
                let words = words_from_block(&self.buf);
                let out = compress(
                    &self.cv,
                    &words,
                    self.chunk_counter,
                    BLOCK_LEN as u32,
                    self.flags | self.start_flag(),
                );
                self.cv.copy_from_slice(&out[..8]);
                self.blocks_compressed += 1;
                self.buf_len = 0;
            }
            let want = BLOCK_LEN - self.buf_len;
            let take = std::cmp::min(want, input.len());
            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&input[..take]);
            self.buf_len += take;
            input = &input[take..];
        }
    }

    fn output(&self) -> Output {
        let mut block = [0u8; BLOCK_LEN];
        block[..self.buf_len].copy_from_slice(&self.buf[..self.buf_len]);
        Output {
            input_cv: self.cv,
            block_words: words_from_block(&block),
            counter: self.chunk_counter,
            block_len: self.buf_len as u32,
            flags: self.flags | self.start_flag() | FLAG_CHUNK_END,
        }
    }
}

fn parent_output(left: [u32; 8], right: [u32; 8], key: [u32; 8], flags: u32) -> Output {
    let mut block_words = [0u32; 16];
    block_words[..8].copy_from_slice(&left);
    block_words[8..].copy_from_slice(&right);
    Output {
        input_cv: key,
        block_words,
        counter: 0,
        block_len: BLOCK_LEN as u32,
        flags: flags | FLAG_PARENT,
    }
}

fn parent_cv(left: [u32; 8], right: [u32; 8], key: [u32; 8], flags: u32) -> [u32; 8] {
    parent_output(left, right, key, flags).chaining_value()
}

pub struct Hasher {
    key: [u32; 8],
    flags: u32,
    chunk: ChunkState,
    cv_stack: Vec<[u32; 8]>,
}

impl Hasher {
    fn new_internal(key: [u32; 8], flags: u32) -> Self {
        Self {
            key,
            flags,
            chunk: ChunkState::new(key, 0, flags),
            cv_stack: Vec::new(),
        }
    }

    pub fn new() -> Self {
        Self::new_internal(IV, 0)
    }

    pub fn new_keyed(key: &[u8; KEY_LEN]) -> Self {
        Self::new_internal(words_from_key(key), FLAG_KEYED_HASH)
    }

    pub fn new_derive_key(context: &str) -> Self {
        // First hash the context string in a dedicated mode to make
        // a context key, then hash the input key material with that
        // key in the material mode.
        let mut context_hasher = Self::new_internal(IV, FLAG_DERIVE_KEY_CONTEXT);
        context_hasher.update(context.as_bytes());
        let context_key_words = context_hasher.finalize_output().chaining_value();
        Self::new_internal(context_key_words, FLAG_DERIVE_KEY_MATERIAL)
    }

    pub fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.chunk.len() as u64 == CHUNK_LEN {
                let chunk_cv = self.chunk.output().chaining_value();
                let total_chunks = self.chunk.chunk_counter + 1;
                let mut cv = chunk_cv;
                let mut total = total_chunks;
                while total & 1 == 0 {
                    let left = self.cv_stack.pop().expect("cv stack underflow");
                    cv = parent_cv(left, cv, self.key, self.flags);
                    total >>= 1;
                }
                self.cv_stack.push(cv);
                self.chunk = ChunkState::new(self.key, total_chunks, self.flags);
            }
            let want = (CHUNK_LEN as usize) - self.chunk.len();
            let take = std::cmp::min(want, input.len());
            self.chunk.update(&input[..take]);
            input = &input[take..];
        }
    }

    pub fn finalize_output(&self) -> Output {
        let mut output = self.chunk.output();
        // Merge the stack from the top down; each merge makes a new
        // parent output whose chaining value feeds the next merge.
        for i in (0..self.cv_stack.len()).rev() {
            output = parent_output(self.cv_stack[i], output.chaining_value(), self.key, self.flags);
        }
        output
    }
}
RS
"}

