mod blake3;

use std::ffi::OsStr;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use clap::{value_parser, Arg, ArgAction, Command};

struct Args {
    files: Vec<PathBuf>,
    keyed: bool,
    derive_key: Option<String>,
    length: u64,
    seek: u64,
    num_threads: Option<usize>,
    no_mmap: bool,
    no_names: bool,
    raw: bool,
    tag: bool,
    check: bool,
    quiet: bool,
}

fn build_command() -> Command {
    Command::new("b3sum")
        .version("1.8.4")
        .arg(
            Arg::new("file")
                .value_name("FILE")
                .help("Files to hash, or checkfiles to check")
                .long_help(
                    "Files to hash, or checkfiles to check\n\nWhen no file is given, or when - is given, read standard input.",
                )
                .num_args(1..)
                .action(ArgAction::Append)
                .value_parser(value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("keyed")
                .long("keyed")
                .help("Use the keyed mode, reading the 32-byte key from stdin")
                .action(ArgAction::SetTrue)
                .conflicts_with("derive_key")
                .requires("file"),
        )
        .arg(
            Arg::new("derive_key")
                .long("derive-key")
                .value_name("CONTEXT")
                .help("Use the key derivation mode, with the given context string")
                .long_help(
                    "Use the key derivation mode, with the given context string\n\nCannot be used with --keyed.",
                )
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("length")
                .short('l')
                .long("length")
                .value_name("LEN")
                .help("The number of output bytes, before hex encoding")
                .default_value("32")
                .value_parser(value_parser!(u64))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("seek")
                .long("seek")
                .value_name("SEEK")
                .help("The starting output byte offset, before hex encoding")
                .default_value("0")
                .value_parser(value_parser!(u64))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("num_threads")
                .long("num-threads")
                .value_name("NUM")
                .help("The maximum number of threads to use")
                .long_help(
                    "The maximum number of threads to use\n\nBy default, this is the number of logical cores. If this flag is omitted, or if its value\nis 0, RAYON_NUM_THREADS is also respected.",
                )
                .value_parser(value_parser!(usize))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("no_mmap")
                .long("no-mmap")
                .help("Disable memory mapping")
                .long_help("Disable memory mapping\n\nCurrently this also disables multithreading.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no_names")
                .long("no-names")
                .help("Omit filenames in the output")
                .action(ArgAction::SetTrue)
                .conflicts_with("check"),
        )
        .arg(
            Arg::new("raw")
                .long("raw")
                .help("Write raw output bytes to stdout, rather than hex")
                .long_help(
                    "Write raw output bytes to stdout, rather than hex\n\n--no-names is implied. In this case, only a single input is allowed.",
                )
                .action(ArgAction::SetTrue)
                .conflicts_with("check"),
        )
        .arg(
            Arg::new("tag")
                .long("tag")
                .help("Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]")
                .action(ArgAction::SetTrue)
                .conflicts_with("check"),
        )
        .arg(
            Arg::new("check")
                .short('c')
                .long("check")
                .help("Read BLAKE3 sums from the [FILE]s and check them")
                .action(ArgAction::SetTrue)
                .conflicts_with_all(["keyed", "derive_key", "length"]),
        )
        .arg(
            Arg::new("quiet")
                .long("quiet")
                .help("Skip printing OK for each checked file")
                .long_help("Skip printing OK for each checked file\n\nMust be used with --check.")
                .action(ArgAction::SetTrue)
                .requires("check"),
        )
}

fn parse_args(matches: &clap::ArgMatches) -> Args {
    Args {
        files: matches
            .get_many::<PathBuf>("file")
            .map(|values| values.cloned().collect())
            .unwrap_or_default(),
        keyed: matches.get_flag("keyed"),
        derive_key: matches.get_one::<String>("derive_key").cloned(),
        length: *matches.get_one::<u64>("length").expect("default length"),
        seek: *matches.get_one::<u64>("seek").expect("default seek"),
        num_threads: matches.get_one::<usize>("num_threads").copied(),
        no_mmap: matches.get_flag("no_mmap"),
        no_names: matches.get_flag("no_names"),
        raw: matches.get_flag("raw"),
        tag: matches.get_flag("tag"),
        check: matches.get_flag("check"),
        quiet: matches.get_flag("quiet"),
    }
}

#[derive(Clone, Copy, PartialEq)]
enum ModeKind {
    Plain,
    Keyed,
    DeriveKey,
}

struct HashMode {
    kind: ModeKind,
    key: Option<[u8; blake3::KEY_LEN]>,
    context: Option<String>,
}

impl HashMode {
    fn hasher(&self) -> blake3::Hasher {
        match self.kind {
            ModeKind::Plain => blake3::Hasher::new(),
            ModeKind::Keyed => blake3::Hasher::new_keyed(
                self.key.as_ref().expect("keyed mode without a key"),
            ),
            ModeKind::DeriveKey => blake3::Hasher::new_derive_key(
                self.context.as_deref().expect("derive mode without context"),
            ),
        }
    }
}

enum InputError {
    Io(io::Error),
    Message(String),
}

impl std::fmt::Display for InputError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            InputError::Io(err) => write!(f, "{}", err),
            InputError::Message(msg) => write!(f, "{}", msg),
        }
    }
}

impl From<io::Error> for InputError {
    fn from(err: io::Error) -> Self {
        InputError::Io(err)
    }
}

fn is_dash(path: &Path) -> bool {
    path.as_os_str() == OsStr::new("-")
}

fn hash_reader<R: Read>(
    reader: &mut R,
    mode: &HashMode,
) -> Result<blake3::Output, InputError> {
    let mut hasher = mode.hasher();
    let mut buffer = [0u8; 65536];
    loop {
        let n = reader.read(&mut buffer)?;
        if n == 0 {
            break;
        }
        hasher.update(&buffer[..n]);
    }
    Ok(hasher.finalize_output())
}

fn hash_path(path: &Path, mode: &HashMode) -> Result<blake3::Output, InputError> {
    if is_dash(path) {
        if mode.kind == ModeKind::Keyed {
            return Err(InputError::Message(
                "Cannot open `-` in keyed mode".to_string(),
            ));
        }
        let stdin = io::stdin();
        let mut locked = stdin.lock();
        hash_reader(&mut locked, mode)
    } else {
        let mut file = File::open(path)?;
        hash_reader(&mut file, mode)
    }
}

fn escape_filename(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for c in name.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            _ => out.push(c),
        }
    }
    out
}

fn print_hash_output(
    path: &Path,
    output: &blake3::Output,
    args: &Args,
) -> Result<(), InputError> {
    if args.raw {
        let mut reader = blake3::XofReader::new(output.clone(), args.seek);
        let mut stdout = io::stdout();
        let mut remaining = args.length;
        let mut buffer = [0u8; 8192];
        while remaining > 0 {
            let take = std::cmp::min(remaining, buffer.len() as u64) as usize;
            reader.fill(&mut buffer[..take]);
            // Deliberately do not flush here; like a plain
            // write_all to the standard output handle.
            use std::io::Write;
            stdout.write_all(&buffer[..take])?;
            remaining -= take as u64;
        }
        return Ok(());
    }

    let filename = path.display().to_string();
    let needs_escape =
        filename.contains('\\') || filename.contains('\n') || filename.contains('\r');
    let shown_name = escape_filename(&filename);

    let (prefix, suffix): (String, String) = if args.no_names {
        (String::new(), String::new())
    } else if args.tag {
        (
            format!(
                "{}BLAKE3 ({}) = ",
                if needs_escape { "\\" } else { "" },
                shown_name
            ),
            String::new(),
        )
    } else {
        (
            if needs_escape {
                "\\".to_string()
            } else {
                String::new()
            },
            format!("  {}", shown_name),
        )
    };

    print!("{}", prefix);
    {
        let mut reader = blake3::XofReader::new(output.clone(), args.seek);
        let mut remaining = args.length;
        let mut raw = [0u8; 8192];
        let mut hexbuf = String::with_capacity(16384);
        while remaining > 0 {
            let take = std::cmp::min(remaining, raw.len() as u64) as usize;
            reader.fill(&mut raw[..take]);
            hexbuf.clear();
            for byte in &raw[..take] {
                // A tiny hand-written hex encoder, so that output
                // can be streamed in chunks of arbitrary length.
                const HEX: &[u8; 16] = b"0123456789abcdef";
                hexbuf.push(HEX[(byte >> 4) as usize] as char);
                hexbuf.push(HEX[(byte & 0xf) as usize] as char);
            }
            print!("{}", hexbuf);
            remaining -= take as u64;
        }
    }
    println!("{}", suffix);
    Ok(())
}

fn hash_and_print_files(args: &Args, mode: &HashMode) -> u8 {
    let mut any_error = false;
    let default_files;
    let files: &[PathBuf] = if args.files.is_empty() {
        default_files = vec![PathBuf::from("-")];
        &default_files
    } else {
        &args.files
    };
    for path in files {
        let result = hash_path(path, mode).and_then(|output| print_hash_output(path, &output, args));
        if let Err(err) = result {
            eprintln!("b3sum: {}: {}", path.display(), err);
            any_error = true;
        }
    }
    if any_error {
        1
    } else {
        0
    }
}

// ---------- check mode ----------

struct ParsedLine {
    expected: [u8; 32],
    raw_filename: String,
    path: PathBuf,
    escaped: bool,
}

fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        _ => None,
    }
}

fn unescape_filename(raw: &str) -> Result<String, &'static str> {
    let mut out = String::with_capacity(raw.len());
    let mut chars = raw.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('n') => out.push('\n'),
            Some('r') => out.push('\r'),
            Some('\\') => out.push('\\'),
            _ => return Err("Invalid backslash escape"),
        }
    }
    Ok(out)
}

fn parse_check_line(line: &str) -> Result<ParsedLine, &'static str> {
    if line.is_empty() {
        return Err("Empty line");
    }
    let escaped = line.starts_with('\\');
    let stripped: &str = if escaped { &line[1..] } else { line };

    // BSD-style lines look like: BLAKE3 (name) = hash
    // They are recognised by the prefix and the last ") = "
    // separator; anything else uses the usual two-space split.
    let bsd_pair: Option<(&str, &str)> = if stripped.starts_with("BLAKE3 (") {
        stripped.rsplit_once(") = ").and_then(|(left, hash)| {
            left.strip_prefix("BLAKE3 (")
                .map(|filename| (hash, filename))
        })
    } else {
        None
    };
    let (hash_str, filename_str): (&str, &str) = match bsd_pair {
        Some(pair) => pair,
        None => match stripped.split_once("  ") {
            Some(pair) => pair,
            None => return Err("Invalid check line format"),
        },
    };

    if hash_str.len() != blake3::OUT_LEN * 2 {
        return Err("Invalid hash length");
    }
    let hash_bytes = hash_str.as_bytes();
    let mut expected = [0u8; 32];
    for i in 0..32 {
        let hi = match hex_value(hash_bytes[i * 2]) {
            Some(v) => v,
            None => return Err("Invalid hex"),
        };
        let lo = match hex_value(hash_bytes[i * 2 + 1]) {
            Some(v) => v,
            None => return Err("Invalid hex"),
        };
        expected[i] = (hi << 4) | lo;
    }

    if filename_str.is_empty() {
        return Err("empty file path");
    }
    let path_str = if escaped {
        unescape_filename(filename_str)?
    } else {
        filename_str.to_string()
    };
    if path_str.contains('\0') {
        return Err("Null character in path");
    }

    Ok(ParsedLine {
        expected,
        raw_filename: filename_str.to_string(),
        path: PathBuf::from(path_str),
        escaped,
    })
}

fn check_reader<R: BufRead>(
    reader: R,
    args: &Args,
    mode: &HashMode,
    failed_count: &mut u64,
) -> anyhow::Result<()> {
    for line_result in reader.lines() {
        let line = line_result?;
        match parse_check_line(&line) {
            Err(message) => {
                eprintln!("b3sum: {}", message);
                *failed_count += 1;
            }
            Ok(parsed) => {
                let display_name = if parsed.escaped {
                    format!("\\{}", parsed.raw_filename)
                } else {
                    parsed.raw_filename.clone()
                };
                match hash_path(&parsed.path, mode) {
                    Ok(output) => {
                        let mut actual = [0u8; 32];
                        let mut xof = blake3::XofReader::new(output, args.seek);
                        xof.fill(&mut actual);
                        if actual == parsed.expected {
                            if !args.quiet {
                                println!("{}: OK", display_name);
                            }
                        } else {
                            println!("{}: FAILED", display_name);
                            *failed_count += 1;
                        }
                    }
                    Err(err) => {
                        println!("{}: FAILED ({})", display_name, err);
                        *failed_count += 1;
                    }
                }
            }
        }
    }
    Ok(())
}

fn check_files(args: &Args, mode: &HashMode) -> anyhow::Result<u8> {
    let mut failed_count: u64 = 0;
    let default_files;
    let files: &[PathBuf] = if args.files.is_empty() {
        default_files = vec![PathBuf::from("-")];
        &default_files
    } else {
        &args.files
    };
    for path in files {
        if is_dash(path) {
            let stdin = io::stdin();
            let locked = stdin.lock();
            check_reader(locked, args, mode, &mut failed_count)?;
        } else {
            let file = File::open(path)?;
            let reader = BufReader::new(file);
            check_reader(reader, args, mode, &mut failed_count)?;
        }
    }
    if failed_count > 0 {
        if failed_count == 1 {
            eprintln!(
                "b3sum: WARNING: {} computed checksum did NOT match",
                failed_count
            );
        } else {
            eprintln!(
                "b3sum: WARNING: {} computed checksums did NOT match",
                failed_count
            );
        }
        Ok(1)
    } else {
        Ok(0)
    }
}

fn read_key() -> anyhow::Result<[u8; blake3::KEY_LEN]> {
    let mut key_bytes = Vec::new();
    io::stdin().take(33).read_to_end(&mut key_bytes)?;
    if key_bytes.len() < blake3::KEY_LEN {
        return Err(anyhow::anyhow!(
            "expected 32 key bytes from stdin, found {}",
            key_bytes.len()
        ));
    }
    if key_bytes.len() > blake3::KEY_LEN {
        return Err(anyhow::anyhow!("read more than 32 key bytes from stdin"));
    }
    let mut key = [0u8; blake3::KEY_LEN];
    key.copy_from_slice(&key_bytes);
    Ok(key)
}

fn run() -> anyhow::Result<u8> {
    let matches = build_command().get_matches();
    let args = parse_args(&matches);

    // The --raw check comes before the key is read from stdin.
    if args.raw && args.files.len() > 1 {
        return Err(anyhow::anyhow!(
            "Only one filename can be provided when using --raw"
        ));
    }

    let mode = if args.keyed {
        let key = read_key()?;
        HashMode {
            kind: ModeKind::Keyed,
            key: Some(key),
            context: None,
        }
    } else if let Some(context) = &args.derive_key {
        HashMode {
            kind: ModeKind::DeriveKey,
            key: None,
            context: Some(context.clone()),
        }
    } else {
        HashMode {
            kind: ModeKind::Plain,
            key: None,
            context: None,
        }
    };

    // Set up the global thread pool used for hashing. A value of
    // zero (or no value) lets the underlying pool honour the
    // RAYON_NUM_THREADS environment variable, as documented.
    rayon::ThreadPoolBuilder::new()
        .num_threads(args.num_threads.unwrap_or(0))
        .build_global_thread_pool()?;

    // The two flags below exist for the hashing back ends; this
    // implementation reads its input, so they need no action.
    let _ = args.no_mmap;

    if args.check {
        check_files(&args, &mode)
    } else {
        Ok(hash_and_print_files(&args, &mode))
    }
}

fn main() -> ExitCode {
    match run() {
        Ok(code) => ExitCode::from(code),
        Err(err) => {
            eprintln!("Error: {:?}", err);
            ExitCode::from(1)
        }
    }
}
