import pty, os, sys
def run(binpath, args, cols):
    pid, fd = pty.fork()
    if pid==0:
        os.execv(binpath, ["executable"]+args)
    else:
        import fcntl, termios, struct
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH",24,cols,0,0))
        out=b""
        try:
            while True:
                d=os.read(fd,4096)
                if not d: break
                out+=d
        except OSError: pass
        _,status=os.waitpid(pid,0)
        return os.waitstatus_to_exitcode(status), out
for cols in [100,80,40,120]:
