            ol=o[1].split(b"\r\n"); nl=n[1].split(b"\r\n")
            for i,(a,b) in enumerate(zip(ol,nl)):
                if a!=b:
                    print(" first diff line",i,a,b); break
            if len(ol)!=len(nl): print(" lines",len(ol),len(nl))
