cat > vendor/terminal_size/src/lib.rs <<'RS'
//! Minimal terminal-size support for Unix-like systems.
//!
//! The size is obtained with the `TIOCGWINSZ` ioctl, trying
//! standard output first, then standard error, then standard
//! input, following the usual convention for command-line tools.

/// The width of a terminal, in columns.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Width(pub u16);

/// The height of a terminal, in rows.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

fn terminal_size_using_fd(fd: i32) -> Option<(Width, Height)> {
    let mut winsize = Winsize::default();
    let result = unsafe { ioctl(fd, TIOCGWINSZ, &mut winsize as *mut Winsize) };
    if result != 0 || winsize.ws_col == 0 {
        return None;
    }
    Some((Width(winsize.ws_col), Height(winsize.ws_row)))
}

/// Returns the size of the terminal, if it can be determined.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_using_fd(1)
        .or_else(|| terminal_size_using_fd(2))
        .or_else(|| terminal_size_using_fd(0))
}

/// Returns the size of the terminal that the supplied file
/// descriptor is connected to, if it can be determined.
pub fn terminal_size_of(fd: i32) -> Option<(Width, Height)> {
    terminal_size_using_fd(fd)
}
