impl Hasher {
    /// Compute the output for a complete in-memory input using the
    /// same key and flags as this (fresh) hasher. Large inputs are
    /// split at the usual tree boundaries and the subtrees are
    /// evaluated in parallel.
    pub fn output_of_input(&self, input: &[u8]) -> Output {
        if input.len() < 32768 {
            let mut hasher = Self::new_internal(self.key, self.flags);
            hasher.update(input);
            return hasher.finalize_output();
        }
        subtree_output(self.key, self.flags, 0, input)
    }
}

fn chunk_output(key: [u32; 8], flags: u32, chunk_counter: u64, input: &[u8]) -> Output {
    let mut chunk = ChunkState::new(key, chunk_counter, flags);
    chunk.update(input);
    chunk.output()
}

fn left_subtree_len(content_len: usize) -> usize {
    // The number of bytes in the largest power-of-two number of
    // chunks that can be placed on the left, always leaving at
    // least one byte for the right-hand side.
    let full_chunks = (content_len - 1) / (CHUNK_LEN as usize);
    let mut power_of_two_chunks = 1usize;
    while power_of_two_chunks * 2 <= full_chunks {
        power_of_two_chunks *= 2;
    }
    power_of_two_chunks * (CHUNK_LEN as usize)
}

fn subtree_output(key: [u32; 8], flags: u32, chunk_counter: u64, input: &[u8]) -> Output {
    if input.len() <= CHUNK_LEN as usize {
        return chunk_output(key, flags, chunk_counter, input);
    }
    let left_len = left_subtree_len(input.len());
    let (left, right) = input.split_at(left_len);
    let right_counter = chunk_counter + (left_len as u64) / CHUNK_LEN;
    let (left_cv, right_cv) = if input.len() >= 262144 {
        rayon::join(
            || subtree_output(key, flags, chunk_counter, left).chaining_value(),
            || subtree_output(key, flags, right_counter, right).chaining_value(),
        )
    } else {
        (
            subtree_output(key, flags, chunk_counter, left).chaining_value(),
            subtree_output(key, flags, right_counter, right).chaining_value(),
        )
    };
    parent_output(left_cv, right_cv, key, flags)
}
