fn bin_display_name() -> String {
    let arg0 = std::env::args_os().next().unwrap_or_default();
    let path = Path::new(&arg0);
    match path.file_name() {
        Some(name) => name.to_string_lossy().into_owned(),
        None => {
            let text = arg0.to_string_lossy().into_owned();
            if text.is_empty() {
                "b3sum".to_string()
            } else {
                text
            }
        }
    }
