// Work around a difference in usage generation for this error
// kind: when another option has already been seen, the usage
// should fall back to an alternation of every argument.
fn has_prior_non_positional_arg(invalid_arg: &str) -> bool {
    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect();
    let Some(offending_index) = args.iter().position(|arg| {
        arg.starts_with("--")
            && arg
                .split_once('=')
                .map(|(name, _value)| name)
                == Some(invalid_arg)
    }) else {
        return false;
    };

    let mut seen = false;
    let mut expecting_value = false;
    let mut after_separator = false;
    for token in &args[..offending_index] {
        if expecting_value {
            expecting_value = false;
            continue;
        }
        if after_separator {
            continue;
        }
        if token == "--" {
            after_separator = true;
            continue;
        }
        if let Some(long) = token.strip_prefix("--") {
            if long.is_empty() {
                continue;
            }
            seen = true;
            let (name, has_inline_value) = match long.split_once('=') {
                Some((name, _value)) => (name, true),
                None => (long, false),
            };
            if !has_inline_value
                && matches!(name, "derive-key" | "length" | "seek" | "num-threads")
            {
                expecting_value = true;
            }
        } else if token.len() > 1 && token.starts_with('-') {
            seen = true;
            let mut chars = token[1..].chars().peekable();
            while let Some(c) = chars.next() {
                if c == 'l' {
                    if chars.peek().is_none() {
                        expecting_value = true;
                    }
                    break;
                }
            }
        }
    }
    seen
}

fn patch_unexpected_value_usage(err: &mut clap::Error) {
    const GROUP: &str = "<FILE|--keyed|--derive-key <CONTEXT>|--length <LEN>|--seek <SEEK>|--num-threads <NUM>|--no-mmap|--no-names|--raw|--tag|--check|--quiet>";
    let invalid_arg = err.context().find_map(|(kind, value)| {
        if kind == ContextKind::InvalidArg {
            Some(value.to_string())
        } else {
            None
        }
    });
    let Some(invalid_arg) = invalid_arg else {
        return;
    };
    if !has_prior_non_positional_arg(&invalid_arg) {
        return;
    }
    let special_prefix = if invalid_arg == "--help" || invalid_arg == "--version" {
        format!("\u{1b}[1m{}\u{1b}[0m ", invalid_arg)
    } else {
        String::new()
    };
    let usage = format!(
        "\u{1b}[1m\u{1b}[4mUsage:\u{1b}[0m \u{1b}[1m{}\u{1b}[0m {}{}",
        bin_display_name(),
        special_prefix,
        GROUP
    );
    err.insert(
        ContextKind::Usage,
        ContextValue::StyledStr(StyledStr::from(usage)),
    );
}

fn get_matches() -> clap::ArgMatches {
    match build_command().try_get_matches() {
        Ok(matches) => matches,
        Err(mut err) => {
            if err.kind() == ErrorKind::TooManyValues {
                patch_unexpected_value_usage(&mut err);
            }
            err.exit()
        }
    }
}

